insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('NE', 'NE-P-10-HEB-ND', 'Hébergement, réception et restauration 10 % non déductible (art. 339 nouveau)', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2026-01-01', null, 'Loi de finances pour 2026 (ordonnance n° 2025-44 du 31 décembre 2025), art. 339 nouveau du Code général des impôts — exclusion du droit à déduction de la taxe sur l''hébergement, la réception, la restauration et les spectacles. Corroboré par le principe déjà posé à l''art. 229 de l''ancien Code général des impôts (2012), sur le logement, l''hébergement, les frais de réception, de restaurant et de spectacles, avec la seule exception du logement gratuit du personnel de surveillance, non retenue ici. La taxe devient une part du coût de la dépense.', 'S', null, 150, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'lf2026', null, null, null, null),
  ('NE', 'NE-P-10-TRANSPORT', 'Transport terrestre de personnes et de marchandises 10 %', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2024-01-01', null, 'Loi de finances pour 2024 (ordonnance n° 2024-001 du 4 janvier 2024), art. 226 nouveau, pour le taux ; Code général des impôts (2012), art. 227, pour la déduction. L''achat d''une prestation de transport de marchandises pour les besoins de l''exploitation n''est pas au nombre des exclusions de l''article 339 nouveau (loi de finances pour 2026), qui ne vise que l''hébergement, la réception, la restauration, les spectacles et les véhicules de transport de personnes.', 'S', null, 140, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2024', null, null, null, null),
  ('NE', 'NE-P-19', 'Achats de biens 19 %', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2012-08-27', null, 'Code général des impôts (2012), art. 227 — déduction de la taxe qui a grevé les biens destinés à être revendus ou les matières premières entrant dans un produit taxable ; art. 226, alinéa 1, pour le taux.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('NE', 'NE-P-19-CADEAU-ND', 'Cadeaux de plus de 20 000 francs CFA hors taxe 19 % non déductible', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2026-01-01', null, 'Loi de finances pour 2026 (ordonnance n° 2025-44 du 31 décembre 2025), art. 339 nouveau du Code général des impôts — exclusion du droit à déduction pour les cadeaux au-delà de 20 000 francs CFA hors taxe. Corroboré par le principe de l''art. 231 de l''ancien Code général des impôts (2012) — biens cédés et services rendus à titre de cadeaux, sans le seuil chiffré, alors non publié.', 'S', null, 180, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'lf2026', null, null, null, null),
  ('NE', 'NE-P-19-IMMO', 'Immobilisations 19 %', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2012-08-27', null, 'Code général des impôts (2012), art. 227 — déduction de la taxe qui a grevé les biens meubles ou immeubles acquis pour les besoins de l''exploitation ; art. 236 à 239 — prorata et régularisations sur les immobilisations.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('NE', 'NE-P-19-SRV', 'Services extérieurs 19 %', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2012-08-27', null, 'Code général des impôts (2012), art. 227 — déduction de la taxe qui a grevé les services entrant dans la réalisation d''opérations taxables, les fournitures et les biens meubles ou immeubles acquis pour les besoins de l''exploitation ; art. 226, alinéa 1, pour le taux.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('NE', 'NE-P-19-VEH-ND', 'Véhicules de transport de personnes 19 % non déductible', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2026-01-01', null, 'Loi de finances pour 2026 (ordonnance n° 2025-44 du 31 décembre 2025), art. 339 nouveau du Code général des impôts — exclusion du droit à déduction pour les véhicules de transport de personnes. Corroboré par l''art. 230 de l''ancien Code général des impôts (2012) — véhicules ou engins conçus ou aménagés pour transporter des personnes ou à usage mixte, constituant une immobilisation ou non destinés à la revente à l''état neuf, ainsi que leurs pièces détachées et accessoires.', 'S', null, 170, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'lf2026', null, null, null, null),
  ('NE', 'NE-P-5', 'Achats de produits de première nécessité et matériel informatique 5 %', '{}'::jsonb, null, 'percent', 5, 'purchase', 'domestic', date '2024-01-01', null, 'Code général des impôts (2012), art. 226, alinéa 2, et loi de finances pour 2024 (ordonnance n° 2024-001 du 4 janvier 2024), art. 226 nouveau, pour le taux ; Code général des impôts (2012), art. 227, pour la déduction.', 'S', null, 160, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2024', null, null, null, null),
  ('NE', 'NE-P-IMP-19', 'Importation 19 % (TVA acquittée en douane)', '{}'::jsonb, null, 'percent', 19, 'purchase', 'import', date '2012-08-27', null, 'Code général des impôts (2012), art. 223-1° — le fait générateur, pour les importations, est l''introduction pour la mise à la consommation des biens sur le territoire nigérien ; art. 224 d) — l''exigibilité intervient à la mise à la consommation ; art. 226, alinéa 3 — la base taxable à l''importation est la valeur en douane majorée du droit de douane, de la redevance statistique et, le cas échéant, du droit d''accises et des surtaxes analogues ; art. 227 — déduction de la taxe acquittée lors de l''importation.', null, null, 190, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('NE', 'NE-S-10-HEB', 'Hébergement et restauration 10 %', '{}'::jsonb, null, 'percent', 10, 'sale', 'domestic', date '2024-01-01', null, 'Loi de finances pour 2024 (ordonnance n° 2024-001 du 4 janvier 2024), art. 226 nouveau — taux réduit de 10 % étendu à l''ensemble de la restauration à compter du 1er janvier 2024 et repris pour l''hébergement, déjà à ce taux avant la loi (date exacte d''introduction non retrouvée). La loi de finances pour 2026 ne réécrit pas cet article.', 'S', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2024', null, null, null, null),
  ('NE', 'NE-S-10-TRANSPORT', 'Transport terrestre de personnes et de marchandises 10 %', '{}'::jsonb, null, 'percent', 10, 'sale', 'domestic', date '2024-01-01', null, 'Loi de finances pour 2024 (ordonnance n° 2024-001 du 4 janvier 2024), art. 226 nouveau — taux réduit de 10 % pour le transport terrestre de personnes et de marchandises, en vigueur depuis le 1er janvier 2024. La loi de finances pour 2026 ne réécrit pas cet article.', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2024', null, null, null, null),
  ('NE', 'NE-S-19', 'Ventes de biens 19 %', '{}'::jsonb, 'Livraisons de biens au taux normal, TVA au compte 4431', 'percent', 19, 'sale', 'domestic', date '2012-08-27', null, 'Code général des impôts (2012), art. 226, alinéa 1 — taux normal de 19 %. L''exposé des motifs de la loi de finances pour 2025 et de celle pour 2026 rappelle ce taux comme en vigueur ; la loi de finances pour 2026 ne réécrit que les articles des exonérations (322 nouveau) et des exclusions du droit à déduction (339 nouveau), pas celui des taux. Le numéro de l''article dans le nouveau Code général des impôts 2026 (ordonnance n° 2025-22 du 14 juillet 2025) n''a pas été vu.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('NE', 'NE-S-19-SRV', 'Prestations de services 19 %', '{}'::jsonb, 'Prestations de services et travaux au taux normal, TVA au compte 4432', 'percent', 19, 'sale', 'domestic', date '2012-08-27', null, 'Code général des impôts (2012), art. 226, alinéa 1, pour le taux ; art. 223-3° — le fait générateur d''une prestation de services est son accomplissement.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('NE', 'NE-S-5', 'Produits de première nécessité et matériel informatique 5 %', '{}'::jsonb, 'Sucre, huile alimentaire, aliments pour bétail, lait manufacturé, farines de maïs, mil, millet, sorgho, riz et blé, matériel informatique pour l''enseignement technique et professionnel (hors consommables)', 'percent', 5, 'sale', 'domestic', date '2024-01-01', null, 'Code général des impôts (2012), art. 226, alinéa 2 — taux réduit de 5 % pour le sucre et l''huile alimentaire depuis 2012 ; loi de finances pour 2024 (ordonnance n° 2024-001 du 4 janvier 2024), art. 226 nouveau — liste élargie aux aliments pour bétail, au lait manufacturé, aux farines énumérées et au matériel informatique pour l''enseignement technique et professionnel hors consommables. La liste lue dans la loi de finances pour 2024 peut être incomplète (coupure de page dans le texte consulté) ; la date d''entrée de chaque produit dans la liste, entre 2012 et 2024, n''a pas été reconstituée.', 'S', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2024', null, null, null, null),
  ('NE', 'NE-S-EXO', 'Opération exonérée (art. 322 nouveau)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'Loi de finances pour 2026 (ordonnance n° 2025-44 du 31 décembre 2025), art. 322 nouveau du Code général des impôts — liste des opérations exonérées : agriculteurs, éleveurs et pêcheurs ; une liste de produits (lait, semences, matériel médical…) ; viandes, fruits et légumes ; professions médicales ; enseignement ; location d''immeubles nus ; avitaillement des aéronefs, transport aérien et aéronefs ; journaux hors publicité ; associations sans but lucratif ; timbres ; opérations non commerciales de l''État ; assurances ; banque et finance (taxe unique) ; mutations soumises aux droits d''enregistrement ; eau (50 m3/mois) et électricité (150 kWh/mois) des ménages ; matériel militaire ; jeux ; musées ; charbon ; lotissements sociaux ; uranium ; or vendu à la SOPAMIN. Une seule case regroupe cette liste, faute de connaître le contenu de l''article 802 nouveau sur les mentions de facture qui permettrait de distinguer chaque motif sur le document.', 'E', null, 70, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'lf2026', null, null, null, null),
  ('NE', 'NE-S-EXP', 'Exportation exonérée', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2026-01-01', null, 'Loi de finances pour 2026 (ordonnance n° 2025-44 du 31 décembre 2025), art. 322-7° nouveau du Code général des impôts — exonération des exportations directes de biens et de services, avec droit à déduction pour les produits taxables à l''intérieur ; loi de finances pour 2025 (ordonnance n° 2024-59 du 31 décembre 2024), art. 228, à la même teneur pour 2025. L''exonération des exportations existait déjà dans l''ancien Code général des impôts (2012) ; seule la date du dernier texte qui la reprend, le 1er janvier 2026, est retenue ici faute d''avoir lu le texte intermédiaire de 2013 à 2023.', 'G', null, 60, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'lf2026', null, null, null, null)
