update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}/{YYYY}/{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Arrêté n° 473/MF/DGI/DL/CFI/DIV.L du 20 novembre 2020, obligatoire depuis le 31 août 2021 pour les régimes réel normal et réel simplifié — chaque facture émise par un Système électronique certifié de facturation (SECeF) porte le numéro d''identification de la machine (NIM) et un code SECeF/DGI attribués par le système, qui l''identifie et le distingue de toute autre facture émise par le même redevable. Aucun article trouvé ne dit, en toutes lettres, une série chronologique et ininterrompue comme le fait le Sénégal (art. 447-I-5) ou la Côte d''Ivoire (Livre de procédures fiscales, art. 145) : le format déclaré ici est celui de la pièce comptable d''un redevable au SECeF, et vaut pour la période où la facture certifiée est obligatoire, non pour toute facture nigérienne en toute période.',
  numbering_source_key          = 'secef',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Code général des impôts (2012), art. 223 — le fait générateur est, pour une vente, la livraison, et pour une prestation de services, l''accomplissement du service ; art. 224 — l''exigibilité suit le fait générateur, mais « la constatation du fait générateur ne peut être postérieure à la facturation totale ou partielle » et l''établissement d''un acompte, d''un décompte provisoire ou d''une facture partielle rend la taxe exigible par avance. invoice_if_issued dit la livraison ou l''accomplissement du service comme principe, devancé par une facture émise plus tôt. Le numéro de ces articles dans le nouveau Code général des impôts 2026 n''a pas été vu.',
  tax_point_source_key          = 'cgi',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Arrêté n° 473/MF/DGI/DL/CFI/DIV.L du 20 novembre 2020 portant commercialisation des Systèmes électroniques certifiés de facturation (SECeF) — dispositif institué par la loi de finances 2020 et renforcé par celle de 2021, phase pilote au 1er octobre 2020, obligatoire depuis le 31 août 2021 pour les assujettis au régime réel normal et au régime réel simplifié ; une facture porte le numéro d''identification de la machine (NIM), le code SECeF/DGI et un code QR. L''obligation elle-même est datée (31 août 2021), mais aucun profil de norme n''est publié et la SECeF n''est pas un format d''échange de la famille EN 16931 : mandatory_from reste vide, une date n''ayant de sens qu''à côté du profil qu''elle rend obligatoire. L''identifiant fiscal est le numéro d''identification fiscale (NIF), sans code ISO 6523 connu.',
  einvoice_source_key           = 'secef',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'NE';
